'use strict';
const attendanceNames={unmarked:'Não marcado',present:'Presente',absent:'Faltou',justified:'Justificada'};
const classUnits={amavale:'Amavale',valparaiso:'Valparaíso','vale-do-carangola':'Vale do Carangola'};
let classSelected='';const attendanceDrafts=new Map();
function todayBR(){const p=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(p=>[p.type,p.value]));return `${p.year}-${p.month}-${p.day}`}
async function classList(){const unit=$('class-unit').value;if(!unit)return;const {classes}=await api('/classes?unit='+unit);$('class-list').replaceChildren();for(const c of classes){const b=el('button',`${c.day.split('-').reverse().join('/')} · ${c.time} · ${c.label}`,{class:'secondary registration-row'});b.addEventListener('click',action(()=>classDetail(c.id)));$('class-list').append(b)}if(!classes.length)$('class-list').append(el('p','Nenhuma chamada aberta neste núcleo. Escolha a turma e a data acima.'))}
async function loadAttendanceGroups(){if(!$('class-unit')?.value)return;const {groups}=await api('/groups?unit='+$('class-unit').value),select=$('class-group'),old=select.value;select.replaceChildren(el('option','Selecione a turma e horário',{value:''}));for(const g of groups.filter(g=>g.active))select.append(el('option',g.label+' · '+g.start_time+'–'+g.end_time+' · '+g.enrolled+' matriculados',{value:g.id}));if(groups.some(g=>g.id===old))select.value=old;await classList()}
async function classDetail(id){classSelected=id;const {lesson,students:rows}=await api('/classes/'+id+'/attendance'),box=$('class-detail');box.hidden=false;box.replaceChildren(el('h3',`${lesson.label} · ${lesson.day.split('-').reverse().join('/')} às ${lesson.time}`),el('p',classUnits[lesson.unit]+' · '+rows.length+' alunos na lista'),el('p','Toque na situação de cada aluno. Revise o resumo e salve no final. Não marcado não conta como falta.'));
 const previous=attendanceDrafts.get(id),draft=new Map(rows.map(r=>{const old=previous?.get(r.id);return [r.id,old?.dirty?old:{status:r.status,version:r.version,dirty:false}]}));attendanceDrafts.set(id,draft);const form=el('form'),summary=el('p','',{role:'status','aria-live':'polite'}),savebar=el('div',undefined,{class:'save-call'}),save=el('button','Salvar chamada');
 const update=()=>{const counts=Object.fromEntries(Object.keys(attendanceNames).map(k=>[k,rows.filter(r=>draft.get(r.id)?.status===k).length]));summary.textContent=Object.entries(attendanceNames).map(([k,v])=>v+': '+counts[k]).join(' · ');save.textContent='Salvar chamada ('+rows.filter(r=>draft.get(r.id)?.status!==r.status).length+' alterações)'};
 for(const r of rows){const line=el('fieldset',undefined,{class:'attendance-person'});line.append(el('legend',r.name),el('small',r.id));const buttons=el('div',undefined,{class:'attendance-options'});for(const [value,label]of Object.entries(attendanceNames)){const b=el('button',value==='unmarked'?'Limpar':label,{type:'button',class:'attendance-choice','aria-pressed':String(draft.get(r.id)?.status===value),'data-status':value});b.addEventListener('click',()=>{draft.set(r.id,{...draft.get(r.id),status:value,dirty:value!==r.status});for(const other of buttons.children)other.setAttribute('aria-pressed',String(other===b));update()});buttons.append(b)}line.append(buttons);form.append(line)}
 update();save.disabled=!!lesson.cancelled;save.dataset.locked=String(!!lesson.cancelled);if(lesson.cancelled)box.append(el('p','Aula cancelada: '+lesson.cancellation_reason,{class:'form-error'}));savebar.append(summary,save);form.append(savebar);form.addEventListener('submit',action(async()=>{const changed=rows.filter(r=>draft.get(r.id)?.status!==r.status).map(r=>({id:r.id,status:draft.get(r.id).status,version:draft.get(r.id).version}));if(!changed.length){notice('Nenhuma marcação alterada.');return}const p=await api('/classes/'+id+'/attendance',{method:'POST',data:{rows:changed}});attendanceDrafts.delete(id);await classDetail(id);notice(p.message+' '+changed.length+' marcações gravadas.');document.dispatchEvent(new Event('portal:attendance-saved'))}));if(rows.length)box.append(form);else box.append(el('p','Esta turma ainda não tem alunos matriculados. A administração deve conferir as matrículas antes de abrir uma nova aula.'));const refresh=el('button','Descartar rascunho e recarregar chamada',{type:'button',class:'secondary'});refresh.addEventListener('click',action(async()=>{attendanceDrafts.delete(id);await classDetail(id)}));box.append(refresh);
 const cancellation=el('details');cancellation.append(el('summary',lesson.cancelled?'Reabrir aula cancelada':'A aula não ocorreu? Registrar cancelamento'));const cf=el('form');field(cf,'Motivo do cancelamento ou reabertura','reason','').required=true;cf.append(el('button',lesson.cancelled?'Reabrir aula':'Confirmar cancelamento'));cf.addEventListener('submit',action(async()=>{const p=await api('/classes/'+id+'/cancellation',{method:'POST',data:{cancelled:!lesson.cancelled,reason:cf.elements.reason.value}});attendanceDrafts.delete(id);await classDetail(id);notice(p.message);document.dispatchEvent(new Event('portal:attendance-saved'))}));cancellation.append(cf);box.append(cancellation);box.scrollIntoView({block:'start'});
}
function setupAttendance(){if($('attendance-area'))return;const area=el('section',undefined,{id:'attendance-area'});$('team-area').before(area);area.append(el('h2','Presença dos alunos'),el('p','1. Escolha núcleo, turma e data. 2. Abra a chamada. 3. Marque os alunos e salve.'));
 const form=el('form',undefined,{id:'class-form'});field(form,'Núcleo da aula','unit','amavale',{options:classUnits,htmlId:'class-unit'});field(form,'Turma e horário','group_id','',{options:{},htmlId:'class-group'}).required=true;field(form,'Data da aula','day',todayBR(),{type:'date',max:todayBR()}).required=true;form.append(el('button','Abrir chamada desta turma'));area.append(form,el('section',undefined,{id:'class-detail',hidden:'',tabindex:'-1'}),el('h3','Chamadas já abertas'),el('div',undefined,{id:'class-list'}));
 $('class-unit').addEventListener('change',action(async()=>{$('class-detail').hidden=true;await loadAttendanceGroups()}));form.addEventListener('submit',action(async()=>{const p=await api('/classes',{method:'POST',data:Object.fromEntries(new FormData(form))});await classList();await classDetail(p.lesson.id)}));
 const exportForm=el('form');exportForm.append(el('h3','Exportar presenças CSV'));field(exportForm,'De','from',todayBR().slice(0,7)+'-01',{type:'date'}).required=true;field(exportForm,'Até','to',todayBR(),{type:'date'}).required=true;exportForm.append(el('button','Baixar presenças CSV'));exportForm.addEventListener('submit',action(async()=>{const values=Object.fromEntries(new FormData(exportForm)),query=new URLSearchParams({...values,unit:$('class-unit').value});download(await api('/attendance.csv?'+query,{blob:true}),'presencas.csv')}));area.append(exportForm);
}
document.addEventListener('portal:loaded',action(async()=>{if(['admin','secretary','teacher'].includes(me.role)){setupAttendance();const {units}=await api('/units');$('attendance-area').hidden=false;const select=$('class-unit'),old=select.value;select.replaceChildren();for(const u of units)select.append(el('option',classUnits[u],{value:u}));if(units.includes(old))select.value=old;if(units.length)await loadAttendanceGroups();else notice('A administração precisa conferir seu cadastro e liberar os núcleos para a chamada.')}else if($('attendance-area'))$('attendance-area').hidden=true}));
document.addEventListener('portal:logout',()=>{$('attendance-area')?.remove();classSelected='';attendanceDrafts.clear()});

import('./rollcall-panel.js').then(({startRollcallPanel})=>startRollcallPanel({api,el,field,action,notice,active:()=>me,showPanel:(id)=>showPanel(id),openCall:async issue=>{
 setupAttendance();$('class-unit').value=issue.unit;await loadAttendanceGroups();$('class-group').value=issue.group_id;$('class-form').elements.day.value=issue.day;showPanel('attendance-area');
 const lesson=issue.class_id?{id:issue.class_id}:(await api('/classes',{method:'POST',data:{unit:issue.unit,group_id:issue.group_id,day:issue.day}})).lesson;
 await classList();await classDetail(lesson.id);
}})).catch(()=>notice('Não foi possível carregar o acompanhamento de chamadas. Atualize a página.'));
